insert into public.chatbot_knowledge (
  id, market_code, category, question, answer, keywords, status, active, updated_at
)
values
  ('10000000-0000-4000-8000-000000000001', 'ALL', 'About', 'What is Stack Petals?', 'Stack Petals combines handcrafted floral gifts with private digital QR keepsakes. Its tagline is “Where Code Meets Blooms,” and its mission is to make thoughtful gifting more personal, lasting, and beautifully connected.', array['about', 'brand', 'mission', 'tagline', 'flowers'], 'approved', true, now()),
  ('10000000-0000-4000-8000-000000000002', 'ALL', 'About', 'Who founded Stack Petals?', 'Stack Petals was founded in May 2026 by Klarenz Evasco, a computer engineer, software builder, designer, and craftsman. Gerlie Evasco is the florist and floral craft partner.', array['founder', 'owner', 'klarenz', 'gerlie', 'team'], 'approved', true, now()),
  ('10000000-0000-4000-8000-000000000003', 'ALL', 'Ordering', 'How do I order from Stack Petals?', 'Choose the correct Philippines or Canada store, browse Shop, select an available gift, and add it to the cart. Philippines customers can continue through checkout. Canada checkout is still being prepared, so Canada customers should use Contact to confirm and place an order.', array['order', 'buy', 'checkout', 'shop', 'how'], 'approved', true, now()),
  ('10000000-0000-4000-8000-000000000004', 'ALL', 'Stores', 'Why are there Philippines and Canada stores?', 'Stack Petals separates the Philippines and Canada stores so customers see products, prices, currency, stock, and availability for the selected country. Changing stores clears an active cart after confirmation.', array['country', 'market', 'store', 'philippines', 'canada', 'currency'], 'approved', true, now()),
  ('10000000-0000-4000-8000-000000000005', 'CA', 'Ordering', 'How do I order from the Canada store?', 'Canada products and Canadian-dollar prices can be browsed on the website, but Canada checkout is currently being prepared. Please use Contact so the Canada store can confirm the product, fulfillment options, total, and payment instructions.', array['canada', 'order', 'checkout', 'cad', 'contact'], 'approved', true, now()),
  ('10000000-0000-4000-8000-000000000006', 'PH', 'Payment', 'How do I pay for a Philippines order?', 'Philippines checkout currently offers GCash or Maya. Scan the selected payment QR, complete payment in that app, and upload a screenshot as payment proof before selecting Complete Order.', array['philippines', 'payment', 'gcash', 'maya', 'proof', 'screenshot'], 'approved', true, now()),
  ('10000000-0000-4000-8000-000000000007', 'PH', 'Payment', 'When will my Philippines payment be confirmed?', 'After a Philippines order is submitted, Stack Petals reviews the uploaded payment proof. The checkout confirmation says the order will be reviewed and confirmed within 24 hours. Use Track Order for the latest status.', array['confirm', 'payment', 'review', '24 hours', 'pending'], 'approved', true, now()),
  ('10000000-0000-4000-8000-000000000008', 'PH', 'Pickup', 'Is Philippines pickup free?', 'Yes. Choosing pickup during Philippines checkout adds no shipping fee. Stack Petals will contact the customer when the handcrafted order is ready for pickup.', array['pickup', 'free', 'shipping', 'fee', 'collect'], 'approved', true, now()),
  ('10000000-0000-4000-8000-000000000009', 'PH', 'Delivery', 'How is the Philippines delivery fee calculated?', 'The delivery fee is estimated from the barangay, city or municipality, and province entered during checkout. The customer should review the displayed shipping fee and final total before payment.', array['delivery', 'shipping', 'fee', 'barangay', 'province', 'address'], 'approved', true, now()),
  ('10000000-0000-4000-8000-000000000010', 'PH', 'Delivery', 'How do I choose a delivery date?', 'Choose an available date during checkout. The website checks daily delivery capacity, and some dates may be limited or full. Pre-order items also require a date that allows the product’s stated preparation time.', array['delivery', 'date', 'slot', 'capacity', 'calendar'], 'approved', true, now()),
  ('10000000-0000-4000-8000-000000000011', 'ALL', 'Pre-order', 'How do Stack Petals pre-orders work?', 'A product marked for pre-order displays its estimated preparation days. Checkout requires a fulfillment date far enough away for that preparation period. Pre-order items are limited to one of each item per checkout.', array['preorder', 'pre-order', 'preparation', 'prep days', 'quantity'], 'approved', true, now()),
  ('10000000-0000-4000-8000-000000000012', 'ALL', 'Stock', 'Why is stock reserved during payment?', 'Available stock may be reserved briefly when the customer continues to payment. Payment should be completed before the displayed reservation time; otherwise the item may return to available stock.', array['stock', 'reserved', 'reservation', 'payment', 'expires'], 'approved', true, now()),
  ('10000000-0000-4000-8000-000000000013', 'ALL', 'Receipt', 'Where can I find my order reference and receipt?', 'The order reference appears after a successful order and begins with “SP-”. Customers can download the checkout receipt, open View Receipt, or use the receipt lookup with the order reference and checkout phone number. Keep the reference for tracking and support.', array['receipt', 'reference', 'order id', 'SP', 'download'], 'approved', true, now()),
  ('10000000-0000-4000-8000-000000000014', 'ALL', 'Tracking', 'What information do I need to track an order?', 'Open Track Order and enter the “SP-” order reference plus the same phone number used during checkout. Petal Guide cannot privately inspect an order or accept those details in chat.', array['track', 'phone', 'reference', 'status', 'private'], 'approved', true, now()),
  ('10000000-0000-4000-8000-000000000015', 'ALL', 'Tracking', 'What order statuses can I see?', 'The tracker can show payment under review, payment confirmed, preparing order, ready, out for delivery, delivered, moved to pre-order, or a payment issue. Pickup orders use pickup wording such as Ready for pickup and Picked up.', array['status', 'pending', 'confirmed', 'preparing', 'ready', 'delivered', 'pickup'], 'approved', true, now()),
  ('10000000-0000-4000-8000-000000000016', 'ALL', 'Receipt', 'Can I print or save my receipt?', 'Yes. After verifying the receipt with the order reference and checkout phone number, use Print / Save PDF. The tracker can also reveal a compact receipt and provides a Save as PDF action.', array['receipt', 'print', 'pdf', 'save'], 'approved', true, now()),
  ('10000000-0000-4000-8000-000000000017', 'ALL', 'Letter Experience', 'Is the personalized letter required?', 'No. The personalized letter is optional during checkout. When included, the customer can provide a recipient name, a main message, six petal messages, an optional song suggestion, and up to three photo memories.', array['letter', 'optional', 'recipient', 'message'], 'approved', true, now()),
  ('10000000-0000-4000-8000-000000000018', 'ALL', 'Letter Experience', 'How long can the main letter message be?', 'The main personalized letter message can contain up to 300 words.', array['letter', 'message', 'limit', 'words', '300'], 'approved', true, now()),
  ('10000000-0000-4000-8000-000000000019', 'ALL', 'Petal Messages', 'How many petal messages can I add?', 'The letter experience has six petal messages. Each petal message can contain up to 60 characters and is revealed when the recipient taps its petal.', array['petal', 'six', '6', 'message', '60 characters', 'limit'], 'approved', true, now()),
  ('10000000-0000-4000-8000-000000000020', 'ALL', 'Memories', 'How many photo memories can I add?', 'Checkout accepts up to three photo memories for the personalized letter experience. They appear as a small memory gallery the recipient can revisit.', array['photo', 'memory', 'memories', 'three', '3', 'upload'], 'approved', true, now()),
  ('10000000-0000-4000-8000-000000000021', 'ALL', 'Music', 'Can I suggest music for the letter?', 'Yes. The song suggestion is optional and can be a song title and artist or a Spotify or YouTube link. It is a request for the background song, and final availability is confirmed by Stack Petals.', array['song', 'music', 'spotify', 'youtube', 'soundtrack'], 'approved', true, now()),
  ('10000000-0000-4000-8000-000000000022', 'ALL', '360 View', 'Does every gift include a 360 view?', 'No. A bouquet 360 view is included only when it is available for that gift. When available, it lets the recipient revisit the finished handcrafted piece from different angles.', array['360', 'view', 'angle', 'available', 'gift'], 'approved', true, now()),
  ('10000000-0000-4000-8000-000000000023', 'ALL', 'QR Keepsake', 'Is the QR keepsake private?', 'The QR tag attached to the handcrafted gift opens the personalized keepsake experience made for its recipient. Customers should share the letter link or QR only with the people they want to access that experience.', array['qr', 'private', 'privacy', 'share', 'link'], 'approved', true, now()),
  ('10000000-0000-4000-8000-000000000024', 'ALL', 'Recipients', 'Who can receive a Stack Petals gift?', 'A Stack Petals gift can be made for a partner, family member, friend, crush, idol, colleague, or anyone meaningful. The personalized wording does not have to be romantic.', array['recipient', 'family', 'friend', 'crush', 'idol', 'anyone'], 'approved', true, now()),
  ('10000000-0000-4000-8000-000000000025', 'ALL', 'Customization', 'What should I include in a custom request?', 'Use Contact and describe the preferred colors, occasion, recipient, message idea, desired date, and any important design details. Stack Petals must confirm materials, schedule, price, and availability before the request is promised.', array['custom', 'request', 'color', 'occasion', 'design'], 'approved', true, now()),
  ('10000000-0000-4000-8000-000000000026', 'PH', 'Contact', 'How can I contact the Philippines store?', 'Use the Contact form, email stack.petals@gmail.com, call +63 962 270 3704, or visit the Stack Petals Facebook page. Listed business hours are Monday to Saturday, 8:00 AM to 7:00 PM.', array['contact', 'email', 'phone', 'hours', 'facebook', 'philippines'], 'approved', true, now()),
  ('10000000-0000-4000-8000-000000000027', 'CA', 'Contact', 'How can I contact the Canada store?', 'Use the website Contact form and select the Canada store before asking about a product or order. Canada-specific ordering, fulfillment, payment, and contact details must be confirmed by the Canada store.', array['canada', 'contact', 'support', 'order'], 'approved', true, now()),
  ('10000000-0000-4000-8000-000000000028', 'ALL', 'Gallery', 'What is shown in the Gallery?', 'The Gallery shows featured Stack Petals arrangements and customer moments selected by the Owner. Customers can filter available gallery categories and open an image for a larger view.', array['gallery', 'photos', 'arrangements', 'featured'], 'approved', true, now()),
  ('10000000-0000-4000-8000-000000000029', 'ALL', 'Reviews', 'Where can I see Stack Petals reviews?', 'Open Reviews from the website navigation to read customer feedback, or open Gallery to see featured crafted pieces.', array['reviews', 'feedback', 'testimonial', 'gallery'], 'approved', true, now()),
  ('10000000-0000-4000-8000-000000000030', 'ALL', 'Support', 'What should I do if I entered something incorrectly or need to change my order?', 'Contact Stack Petals as soon as possible and include the order reference. Changes are not guaranteed because payment review, stock reservation, preparation, and delivery scheduling may already be in progress.', array['change', 'incorrect', 'mistake', 'edit', 'order', 'support'], 'approved', true, now()),
  ('10000000-0000-4000-8000-000000000031', 'ALL', 'Support', 'What is the cancellation or refund policy?', 'The public website does not currently state a universal cancellation or refund policy. Contact Stack Petals with the order reference so the store can review the specific order; Petal Guide must not promise a refund or cancellation.', array['cancel', 'cancellation', 'refund', 'policy'], 'approved', true, now()),
  ('10000000-0000-4000-8000-000000000032', 'ALL', 'Navigation', 'Where can I learn how Stack Petals works?', 'Open Process to see the full journey: choose a gift, personalize it, complete checkout, let Stack Petals craft and prepare it, then receive it through pickup or delivery. Process also previews the QR, letter, memories, music, and 360 experience.', array['process', 'how', 'works', 'journey', 'steps'], 'approved', true, now()),
  ('10000000-0000-4000-8000-000000000033', 'ALL', 'Support', 'What can Petal Guide help me with?', 'Petal Guide can answer customer questions about Stack Petals products, availability, ordering, Philippines and Canada stores, checkout, payment, pickup or delivery, pre-orders, customization, QR keepsakes, letters, petal messages, memories, music, 360 views, receipts, tracking, Gallery, Reviews, and Contact. It cannot access private order records or confidential business data.', array['help', 'chatbot', 'petal guide', 'know', 'questions', 'everything', 'support'], 'approved', true, now())
on conflict (id) do update set
  market_code = excluded.market_code,
  category = excluded.category,
  question = excluded.question,
  answer = excluded.answer,
  keywords = excluded.keywords,
  status = excluded.status,
  active = excluded.active,
  updated_at = excluded.updated_at;
